// Directional sun glow and a softly visible sky disc.
const sunBall=new THREE.Mesh(new THREE.SphereGeometry(3,24,16),new THREE.MeshBasicMaterial({color:0xffd99d}));sunBall.position.set(-62,45,-105);scene.add(sunBall);

const $=id=>document.getElementById(id), keys=new Set();
const ui={score:$('score'),timer:$('timer'),speed:$('speed'),status:$('status'),combo:$('combo'),comboDetail:$('comboDetail'),comboWrap:$('comboWrap'),airMeter:$('airMeter'),airValue:$('airValue'),toast:$('toast'),overlay:$('overlay'),card:$('card')};
let running=false, finished=false, score=0, timeLeft=120, speed=0, yaw=0, vy=0, grounded=true, airtime=0, spin=0, trickBank=0, comboCount=0, comboAge=0, comboPoints=0, grindTime=0, wipeLock=0, toastAge=0, ollieLock=0, nearRamp=false, currentRamp=null, landingFlash=0;
const pos=skater.position, clock=new THREE.Clock();
const trickNames={z:['KICKFLIP',500],x:['INDY GRAB',650],c:['360 SHUVIT',700],q:['HEELFLIP',600],e:['MELON GRAB',750]};
function showToast(text){ui.toast.textContent=text;ui.toast.classList.add('show');toastAge=.95}
function startSession(){score=0;timeLeft=120;speed=0;yaw=0;pos.set(0,0,-13);vy=0;grounded=true;airtime=0;spin=0;trickBank=0;comboCount=0;comboAge=0;comboPoints=0;grindTime=0;wipeLock=0;finished=false;running=true;rider.rotation.set(0,0,0);skater.rotation.y=0;ui.overlay.classList.add('hidden');showToast('LET’S ROLL');}
function endSession(){running=false;finished=true;ui.card.innerHTML=`<div class="kicker">SESSION COMPLETE · CITY PARK</div><h1>Run it<br><span>back.</span></h1><div class="card-copy">The streets are yours. Every clean landing adds to your line.</div><div class="result-score">${score.toLocaleString()}</div><div class="result-label">TOTAL SESSION SCORE</div><div style="height:22px"></div><button class="start-btn" id="startBtn">SKATE AGAIN &nbsp; ↗</button><div class="card-foot">BEST LINES ARE BUILT ONE TRICK AT A TIME</div>`;ui.overlay.classList.remove('hidden');$('startBtn').addEventListener('click',startSession);}
$('startBtn').addEventListener('click',startSession);
const preventKeys=new Set([' ','ArrowUp','ArrowDown','ArrowLeft','ArrowRight']);
addEventListener('keydown',e=>{if(preventKeys.has(e.key))e.preventDefault();const k=e.key.toLowerCase();if(!keys.has(k)){keys.add(k);if(running)onPress(k)}if(k==='escape'&&running){running=false;ui.card.innerHTML='<div class="kicker">SESSION PAUSED</div><h1>Catch<br><span>your breath.</span></h1><div class="card-copy">Your line is waiting.</div><div style="height:22px"></div><button class="start-btn" id="startBtn">KEEP SKATING &nbsp; ↗</button><div class="card-foot">SESSION CLOCK PAUSED</div>';ui.overlay.classList.remove('hidden');$('startBtn').addEventListener('click',()=>{running=true;ui.overlay.classList.add('hidden')})}});
addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
addEventListener('blur',()=>keys.clear());
function onPress(k){
 if(k===' '||k==='arrowup'){if(grounded&&ollieLock<=0){vy=5.8+Math.min(speed*.1,1.8);grounded=false;airtime=0;trickBank=0;spin=0;ollieLock=.28;showToast('OLLIE!')}}
 else if(!grounded&&trickNames[k]){const [name,base]=trickNames[k];trickBank+=base;comboCount++;rider.rotation.x=(k==='x'||k==='e')?.36:rider.rotation.x;skater.rotation.y+=k==='c'?Math.PI*2:(Math.random()-.5)*.8;showToast(name);}
}
function updateGame(dt){
 if(!running)return;
 timeLeft=Math.max(0,timeLeft-dt);if(timeLeft===0){endSession();return}
 ollieLock=Math.max(0,ollieLock-dt);wipeLock=Math.max(0,wipeLock-dt);comboAge+=dt;landingFlash=Math.max(0,landingFlash-dt);
 const forward=keys.has('w')||keys.has('arrowup'), reverse=keys.has('s')||keys.has('arrowdown'), left=keys.has('a')||keys.has('arrowleft'), right=keys.has('d')||keys.has('arrowright'), slide=keys.has('shift');
 if(forward)speed+=7.8*dt;else if(reverse)speed-=10*dt;else speed-=.72*dt;
 speed=THREE.MathUtils.clamp(speed,0,17);
 if(left)yaw+=dt*(1.55+speed*.04);if(right)yaw-=dt*(1.55+speed*.04);
 if(slide){speed=Math.max(0,speed-5*dt);yaw+=((left?1:0)-(right?1:0))*dt*1.1;}
 const dx=Math.sin(yaw)*speed*dt, dz=Math.cos(yaw)*speed*dt;
 pos.x+=dx;pos.z+=dz;
 // Cross a sloped bank face and launch from its coping.
 nearRamp=false;currentRamp=null;
 for(const r of ramps){const ca=Math.cos(r.rotation),sa=Math.sin(r.rotation),rx=pos.x-r.x,rz=pos.z-r.z;const lx=rx*ca-rz*sa,lz=rx*sa+rz*ca;
  if(Math.abs(lx)<r.w*.5&&lz>=-.3&&lz<=r.len*.5+.2&&Math.abs(pos.y)<2.7){nearRamp=true;currentRamp=r;const face=THREE.MathUtils.clamp(lz/(r.len*.5),0,1)*r.h;pos.y=Math.max(pos.y,face);
   if(lz>=r.len*.5-.3&&grounded&&speed>3){vy=3.1+Math.min(speed*.22,3.8);grounded=false;airtime=0;trickBank=0;spin=0;showToast('RAMP POP!');}
  }
 }
 // Gravity and clean touchdown scoring.
 if(!grounded){vy-=12*dt;pos.y+=vy*dt;airtime+=dt;spin+=dt*(keys.has('c')?5:0);if(pos.y<=0&&vy<0){pos.y=0;vy=0;grounded=true;landingFlash=.4;rider.rotation.x=0;
   if(wipeLock<=0){let airBonus=Math.round(airtime*160);let raw=trickBank+airBonus+(comboCount>1?comboCount*140:0);if(raw>0){const multiplier=Math.min(1+Math.max(comboCount-1,0)*.5,4);const earned=Math.round(raw*multiplier);score+=earned;comboPoints+=earned;comboAge=0;ui.combo.textContent=comboCount>1?'SICK LINE!':'CLEAN LANDING';ui.comboDetail.textContent=`+${earned.toLocaleString()} · ${multiplier.toFixed(1)}× MULTIPLIER`;ui.comboWrap.classList.add('on');showToast('+'+earned.toLocaleString());}else if(airtime>.18)showToast('STUCK IT!');
   }else{speed*=.48;comboCount=0;comboPoints=0;trickBank=0;showToast('WIPEOUT');}
   airtime=0;trickBank=0;comboCount=0;wipeLock=.22;
  }}
 // Ride along a rail when close enough; the grind itself scores continuously.
 let onRail=false;
 for(const r of rails){const da=pos.x-r.x,dz0=pos.z-r.z;const along=da*Math.sin(r.rot)+dz0*Math.cos(r.rot),side=da*Math.cos(r.rot)-dz0*Math.sin(r.rot);
  if(Math.abs(along)<r.len/2&&Math.abs(side)<.68&&pos.y<1.6&&speed>1.5){onRail=true;grounded=true;vy=0;pos.y=.98;grindTime+=dt;const gain=Math.floor(dt*260* Math.max(1,speed/7));score+=gain;comboPoints+=gain;comboAge=0;ui.combo.textContent='50–50 GRIND';ui.comboDetail.textContent=`+${Math.floor(grindTime*260).toLocaleString()} · KEEP BALANCE`;ui.comboWrap.classList.add('on');ui.status.textContent='LOCKED ON · GRIND!';break;}}
 if(!onRail)grindTime=0;
 // Keep the action inside the skate plaza.
 pos.x=THREE.MathUtils.clamp(pos.x,-46,46);pos.z=THREE.MathUtils.clamp(pos.z,-40,91);
 if(comboAge>2.1&&!onRail){ui.comboWrap.classList.remove('on');comboPoints=0}
 const rolling=grounded?0:Math.sin(performance.now()*.012)*.045;
 skater.position.y=pos.y+rolling;skater.rotation.y=yaw;
 board.position.y=.08+(grounded?0:Math.sin(airtime*9)*.13);board.rotation.z=grounded?(slide?Math.sin(performance.now()*.008)*.18:0):Math.sin(airtime*17)*.21;
 rider.position.y=grounded?0:Math.sin(airtime*12)*.045; rider.rotation.z=grounded?(left?.06:right?-.06:0):Math.sin(airtime*8)*.1;
 if(!grounded&&trickBank>0)rider.rotation.x=Math.sin(performance.now()*.02)*.16;
 if(grounded&&onRail)rider.rotation.z=Math.sin(performance.now()*.02)*.07;
 // The chase camera eases in behind the current line.
 const camTarget=new THREE.Vector3(pos.x-Math.sin(yaw)*9,5.3+pos.y,pos.z-Math.cos(yaw)*9);
 camera.position.lerp(camTarget,1-Math.pow(.001,dt));camera.lookAt(pos.x,1.05+pos.y,pos.z+2.4);
 const km=Math.round(speed*3.1);ui.speed.textContent=String(km).padStart(2,'0');
 ui.status.textContent=onRail?'LOCKED ON · GRIND!':!grounded?(trickBank?'TRICK IN PROGRESS':'AIRBORNE · THROW A TRICK'):forward?'BUILDING SPEED':speed>1?'ROLLING CLEAN':'PUSH TO BUILD SPEED';
 ui.airMeter.style.width=`${Math.min(100,grounded?0:(airtime*48+trickBank/48))}%`;ui.airValue.textContent=grounded?'READY':`${(airtime).toFixed(1)}s AIR`;
 ui.score.textContent=String(score).padStart(6,'0');const sec=Math.ceil(timeLeft);ui.timer.textContent=`${Math.floor(sec/60)}:${String(sec%60).padStart(2,'0')}`;ui.timer.classList.toggle('danger',timeLeft<20);
}

